python3 -I - <<'EOF'
import glob,collections
files=[f for f in glob.glob('**/*.md',recursive=True) if 'agent-history' not in f and 'official' not in f and 'node_modules' not in f]+['AGENTS.md']
seen=collections.defaultdict(list)
for f in set(files):
    for i,p in enumerate(open(f,encoding='utf-8').read().split('\n\n')):
        p=p.strip()
        if len(p)>80: seen[p[:120]].append(f)
for k,v in seen.items():
    if len(v)>1: print(len(v),sorted(set(v)),k[:70])
